window.RTLBenchLSData.register("assets/f4a9d4392aab3e6765d201d86dcd1350b9d1f5d6add016bbc5c79da1e1ac5060.txt","/**************************************************************************\r\n*\r\n*    File Name:  MT48LC2M32B2.V  \r\n*      Version:  2.1\r\n*         Date:  June 6th, 2002\r\n*        Model:  BUS Functional\r\n*    Simulator:  Model Technology\r\n*\r\n* Dependencies:  None\r\n*\r\n*        Email:  modelsupport@micron.com\r\n*      Company:  Micron Technology, Inc.\r\n*        Model:  MT48LC2M32B2 (512K x 32 x 4 Banks)\r\n*\r\n*  Description:  Micron 64Mb SDRAM Verilog model\r\n*\r\n*   Limitation:  - Doesn't check for 4096 cycle refresh\r\n*\r\n*         Note:  - Set simulator resolution to \"ps\" accuracy\r\n*                - Set Debug = 0 to disable $display messages\r\n*\r\n*   Disclaimer:  THESE DESIGNS ARE PROVIDED \"AS IS\" WITH NO WARRANTY \r\n*                WHATSOEVER AND MICRON SPECIFICALLY DISCLAIMS ANY \r\n*                IMPLIED WARRANTIES OF MERCHANTABILITY, FITNESS FOR\r\n*                A PARTICULAR PURPOSE, OR AGAINST INFRINGEMENT.\r\n*\r\n*                Copyright � 2001 Micron Semiconductor Products, Inc.\r\n*                All rights researved\r\n*\r\n* Rev  Author          Date        Changes\r\n* ---  --------------------------  ---------------------------------------\r\n* 2.1  SH              06/06/2002  - Typo in bank multiplex\r\n*      Micron Technology Inc.\r\n*\r\n* 2.0  SH              04/30/2002  - Second release\r\n*      Micron Technology Inc.\r\n*\r\n**************************************************************************/\r\n\r\n`timescale 1ns / 1ps\r\n\r\nmodule mt48lc2m32b2 (Dq, Addr, Ba, Clk, Cke, Cs_n, Ras_n, Cas_n, We_n, Dqm);\r\n\r\n    parameter addr_bits =      11;\r\n    parameter data_bits =      32;\r\n    parameter col_bits  =       8;\r\n    parameter mem_sizes =  524287;\r\n\r\n    inout     [data_bits - 1 : 0] Dq;\r\n    input     [addr_bits - 1 : 0] Addr;\r\n    input                 [1 : 0] Ba;\r\n    input                         Clk;\r\n    input                         Cke;\r\n    input                         Cs_n;\r\n    input                         Ras_n;\r\n    input                         Cas_n;\r\n    input                         We_n;\r\n    input                 [3 : 0] Dqm;\r\n\r\n    reg       [data_bits - 1 : 0] Bank0 [0 : mem_sizes];\r\n    reg       [data_bits - 1 : 0] Bank1 [0 : mem_sizes];\r\n    reg       [data_bits - 1 : 0] Bank2 [0 : mem_sizes];\r\n    reg       [data_bits - 1 : 0] Bank3 [0 : mem_sizes];\r\n\r\n    reg                   [1 : 0] Bank_addr [0 : 3];                // Bank Address Pipeline\r\n    reg        [col_bits - 1 : 0] Col_addr [0 : 3];                 // Column Address Pipeline\r\n    reg                   [3 : 0] Command [0 : 3];                  // Command Operation Pipeline\r\n    reg                   [3 : 0] Dqm_reg0, Dqm_reg1;               // DQM Operation Pipeline\r\n    reg       [addr_bits - 1 : 0] B0_row_addr, B1_row_addr, B2_row_addr, B3_row_addr;\r\n\r\n    reg       [addr_bits - 1 : 0] Mode_reg;\r\n    reg       [data_bits - 1 : 0] Dq_reg, Dq_dqm;\r\n    reg        [col_bits - 1 : 0] Col_temp, Burst_counter;\r\n\r\n    reg                           Act_b0, Act_b1, Act_b2, Act_b3;   // Bank Activate\r\n    reg                           Pc_b0, Pc_b1, Pc_b2, Pc_b3;       // Bank Precharge\r\n\r\n    reg                   [1 : 0] Bank_precharge       [0 : 3];     // Precharge Command\r\n    reg                           A10_precharge        [0 : 3];     // Addr[10] = 1 (All banks)\r\n    reg                           Auto_precharge       [0 : 3];     // RW Auto Precharge (Bank)\r\n    reg                           Read_precharge       [0 : 3];     // R  Auto Precharge\r\n    reg                           Write_precharge      [0 : 3];     //  W Auto Precharge\r\n    reg                           RW_interrupt_read    [0 : 3];     // RW Interrupt Read with Auto Precharge\r\n    reg                           RW_interrupt_write   [0 : 3];     // RW Interrupt Write with Auto Precharge\r\n    reg                   [1 : 0] RW_interrupt_bank;                // RW Interrupt Bank\r\n    integer                       RW_interrupt_counter [0 : 3];     // RW Interrupt Counter\r\n    integer                       Count_precharge      [0 : 3];     // RW Auto Precharge Counter\r\n\r\n    reg                           Data_in_enable;\r\n    reg                           Data_out_enable;\r\n\r\n    reg                   [1 : 0] Bank, Prev_bank;\r\n    reg       [addr_bits - 1 : 0] Row;\r\n    reg        [col_bits - 1 : 0] Col, Col_brst;\r\n\r\n    // Internal system clock\r\n    reg                           CkeZ, Sys_clk;\r\n\r\n    // Commands Decode\r\n    wire      Active_enable    = ~Cs_n & ~Ras_n &  Cas_n &  We_n;\r\n    wire      Aref_enable      = ~Cs_n & ~Ras_n & ~Cas_n &  We_n;\r\n    wire      Burst_term       = ~Cs_n &  Ras_n &  Cas_n & ~We_n;\r\n    wire      Mode_reg_enable  = ~Cs_n & ~Ras_n & ~Cas_n & ~We_n;\r\n    wire      Prech_enable     = ~Cs_n & ~Ras_n &  Cas_n & ~We_n;\r\n    wire      Read_enable      = ~Cs_n &  Ras_n & ~Cas_n &  We_n;\r\n    wire      Write_enable     = ~Cs_n &  Ras_n & ~Cas_n & ~We_n;\r\n\r\n    // Burst Length Decode\r\n    wire      Burst_length_1   = ~Mode_reg[2] & ~Mode_reg[1] & ~Mode_reg[0];\r\n    wire      Burst_length_2   = ~Mode_reg[2] & ~Mode_reg[1] &  Mode_reg[0];\r\n    wire      Burst_length_4   = ~Mode_reg[2] &  Mode_reg[1] & ~Mode_reg[0];\r\n    wire      Burst_length_8   = ~Mode_reg[2] &  Mode_reg[1] &  Mode_reg[0];\r\n    wire      Burst_length_f   =  Mode_reg[2] &  Mode_reg[1] &  Mode_reg[0];\r\n\r\n    // CAS Latency Decode\r\n    wire      Cas_latency_1    = ~Mode_reg[6] & ~Mode_reg[5] &  Mode_reg[4];\r\n    wire      Cas_latency_2    = ~Mode_reg[6] &  Mode_reg[5] & ~Mode_reg[4];\r\n    wire      Cas_latency_3    = ~Mode_reg[6] &  Mode_reg[5] &  Mode_reg[4];\r\n\r\n    // Write Burst Mode\r\n    wire      Write_burst_mode = Mode_reg[9];\r\n\r\n    wire      Debug            = 1'b1;                          // Debug messages : 1 = On\r\n    wire      Dq_chk           = Sys_clk & Data_in_enable;      // Check setup/hold time for DQ\r\n    \r\n    assign    Dq               = Dq_reg;                        // DQ buffer\r\n\r\n    // Commands Operation\r\n    `define   ACT       0\r\n    `define   NOP       1\r\n    `define   READ      2\r\n    `define   WRITE     3\r\n    `define   PRECH     4\r\n    `define   A_REF     5\r\n    `define   BST       6\r\n    `define   LMR       7\r\n\r\n    // Timing Parameters for -6 CL3\r\n    parameter tAC  =   5.5;\r\n    parameter tHZ  =   5.5;\r\n    parameter tOH  =   2.5;\r\n    parameter tMRD =   2.0;     // 2 Clk Cycles\r\n    parameter tRAS =  42.0;\r\n    parameter tRC  =  60.0;\r\n    parameter tRCD =  18.0;\r\n    parameter tRFC =  60.0;\r\n    parameter tRP  =  18.0;\r\n    parameter tRRD =  12.0;\r\n    parameter tWRa =   6.0;     // A2 Version - Auto precharge mode (1 Clk + 7 ns)\r\n    parameter tWRm =  12.0;     // A2 Version - Manual precharge mode (14 ns)\r\n\r\n    // Timing Check variable\r\n    time  MRD_chk;\r\n    time  WR_chkm [0 : 3];\r\n    time  RFC_chk, RRD_chk;\r\n    time  RC_chk0, RC_chk1, RC_chk2, RC_chk3;\r\n    time  RAS_chk0, RAS_chk1, RAS_chk2, RAS_chk3;\r\n    time  RCD_chk0, RCD_chk1, RCD_chk2, RCD_chk3;\r\n    time  RP_chk0, RP_chk1, RP_chk2, RP_chk3;\r\n\r\n    initial begin\r\n        Dq_reg = {data_bits{1'bz}};\r\n        Data_in_enable = 0; Data_out_enable = 0;\r\n        Act_b0 = 1; Act_b1 = 1; Act_b2 = 1; Act_b3 = 1;\r\n        Pc_b0 = 0; Pc_b1 = 0; Pc_b2 = 0; Pc_b3 = 0;\r\n        WR_chkm[0] = 0; WR_chkm[1] = 0; WR_chkm[2] = 0; WR_chkm[3] = 0;\r\n        RW_interrupt_read[0] = 0; RW_interrupt_read[1] = 0; RW_interrupt_read[2] = 0; RW_interrupt_read[3] = 0;\r\n        RW_interrupt_write[0] = 0; RW_interrupt_write[1] = 0; RW_interrupt_write[2] = 0; RW_interrupt_write[3] = 0;\r\n        MRD_chk = 0; RFC_chk = 0; RRD_chk = 0;\r\n        RAS_chk0 = 0; RAS_chk1 = 0; RAS_chk2 = 0; RAS_chk3 = 0;\r\n        RCD_chk0 = 0; RCD_chk1 = 0; RCD_chk2 = 0; RCD_chk3 = 0;\r\n        RC_chk0 = 0; RC_chk1 = 0; RC_chk2 = 0; RC_chk3 = 0;\r\n        RP_chk0 = 0; RP_chk1 = 0; RP_chk2 = 0; RP_chk3 = 0;\r\n        $timeformat (-9, 1, \" ns\", 12);\r\n    end\r\n\r\n    // System clock generator\r\n    always begin\r\n        @ (posedge Clk) begin\r\n            Sys_clk = CkeZ;\r\n            CkeZ = Cke;\r\n        end\r\n        @ (negedge Clk) begin\r\n            Sys_clk = 1'b0;\r\n        end\r\n    end\r\n\r\n    always @ (posedge Sys_clk) begin\r\n        // Internal Commamd Pipelined\r\n        Command[0] = Command[1];\r\n        Command[1] = Command[2];\r\n        Command[2] = Command[3];\r\n        Command[3] = `NOP;\r\n\r\n        Col_addr[0] = Col_addr[1];\r\n        Col_addr[1] = Col_addr[2];\r\n        Col_addr[2] = Col_addr[3];\r\n        Col_addr[3] = {col_bits{1'b0}};\r\n\r\n        Bank_addr[0] = Bank_addr[1];\r\n        Bank_addr[1] = Bank_addr[2];\r\n        Bank_addr[2] = Bank_addr[3];\r\n        Bank_addr[3] = 2'b0;\r\n\r\n        Bank_precharge[0] = Bank_precharge[1];\r\n        Bank_precharge[1] = Bank_precharge[2];\r\n        Bank_precharge[2] = Bank_precharge[3];\r\n        Bank_precharge[3] = 2'b0;\r\n\r\n        A10_precharge[0] = A10_precharge[1];\r\n        A10_precharge[1] = A10_precharge[2];\r\n        A10_precharge[2] = A10_precharge[3];\r\n        A10_precharge[3] = 1'b0;\r\n\r\n        // Dqm pipeline for Read\r\n        Dqm_reg0 = Dqm_reg1;\r\n        Dqm_reg1 = Dqm;\r\n\r\n        // Read or Write with Auto Precharge Counter\r\n        if (Auto_precharge[0] === 1'b1) begin\r\n            Count_precharge[0] = Count_precharge[0] + 1;\r\n        end\r\n        if (Auto_precharge[1] === 1'b1) begin\r\n            Count_precharge[1] = Count_precharge[1] + 1;\r\n        end\r\n        if (Auto_precharge[2] === 1'b1) begin\r\n            Count_precharge[2] = Count_precharge[2] + 1;\r\n        end\r\n        if (Auto_precharge[3] === 1'b1) begin\r\n            Count_precharge[3] = Count_precharge[3] + 1;\r\n        end\r\n\r\n        // Read or Write Interrupt Counter\r\n        if (RW_interrupt_write[0] === 1'b1) begin\r\n            RW_interrupt_counter[0] = RW_interrupt_counter[0] + 1;\r\n        end\r\n        if (RW_interrupt_write[1] === 1'b1) begin\r\n            RW_interrupt_counter[1] = RW_interrupt_counter[1] + 1;\r\n        end\r\n        if (RW_interrupt_write[2] === 1'b1) begin\r\n            RW_interrupt_counter[2] = RW_interrupt_counter[2] + 1;\r\n        end\r\n        if (RW_interrupt_write[3] === 1'b1) begin\r\n            RW_interrupt_counter[3] = RW_interrupt_counter[3] + 1;\r\n        end\r\n\r\n        // tMRD Counter\r\n        MRD_chk = MRD_chk + 1;\r\n\r\n        // Auto Refresh\r\n        if (Aref_enable === 1'b1) begin\r\n            if (Debug) begin\r\n                $display (\"%m : at time %t AREF : Auto Refresh\", $time);\r\n            end\r\n\r\n            // Auto Refresh to Auto Refresh\r\n            if ($time - RFC_chk < tRFC) begin\r\n                $display (\"%m : at time %t ERROR: tRFC violation during Auto Refresh\", $time);\r\n            end\r\n\r\n            // Precharge to Auto Refresh\r\n            if (($time - RP_chk0 < tRP) || ($time - RP_chk1 < tRP) ||\r\n                ($time - RP_chk2 < tRP) || ($time - RP_chk3 < tRP)) begin\r\n                $display (\"%m : at time %t ERROR: tRP violation during Auto Refresh\", $time);\r\n            end\r\n\r\n            // Precharge to Refresh\r\n            if (Pc_b0 === 1'b0 || Pc_b1 === 1'b0 || Pc_b2 === 1'b0 || Pc_b3 === 1'b0) begin\r\n                $display (\"%m : at time %t ERROR: All banks must be Precharge before Auto Refresh\", $time);\r\n            end\r\n\r\n            // Load Mode Register to Auto Refresh\r\n            if (MRD_chk < tMRD) begin\r\n                $display (\"%m : at time %t ERROR: tMRD violation during Auto Refresh\", $time);\r\n            end\r\n\r\n            // Record Current tRFC time\r\n            RFC_chk = $time;\r\n        end\r\n        \r\n        // Load Mode Register\r\n        if (Mode_reg_enable === 1'b1) begin\r\n            // Register Mode\r\n            Mode_reg = Addr;\r\n\r\n            // Decode CAS Latency, Burst Length, Burst Type, and Write Burst Mode\r\n            if (Debug) begin\r\n                $display (\"%m : at time %t LMR  : Load Mode Register\", $time);\r\n                // CAS Latency\r\n                case (Addr[6 : 4])\r\n                    3'b001  : $display (\"%m :                             CAS Latency      = 1\");\r\n                    3'b010  : $display (\"%m :                             CAS Latency      = 2\");\r\n                    3'b011  : $display (\"%m :                             CAS Latency      = 3\");\r\n                    default : $display (\"%m :                             CAS Latency      = Reserved\");\r\n                endcase\r\n\r\n                // Burst Length\r\n                case (Addr[2 : 0])\r\n                    3'b000  : $display (\"%m :                             Burst Length     = 1\");\r\n                    3'b001  : $display (\"%m :                             Burst Length     = 2\");\r\n                    3'b010  : $display (\"%m :                             Burst Length     = 4\");\r\n                    3'b011  : $display (\"%m :                             Burst Length     = 8\");\r\n                    3'b111  : $display (\"%m :                             Burst Length     = Full\");\r\n                    default : $display (\"%m :                             Burst Length     = Reserved\");\r\n                endcase\r\n\r\n                // Burst Type\r\n                if (Addr[3] === 1'b0) begin\r\n                    $display (\"%m :                             Burst Type       = Sequential\");\r\n                end else if (Addr[3] === 1'b1) begin\r\n                    $display (\"%m :                             Burst Type       = Interleaved\");\r\n                end else begin\r\n                    $display (\"%m :                             Burst Type       = Reserved\");\r\n                end\r\n\r\n                // Write Burst Mode\r\n                if (Addr[9] === 1'b0) begin\r\n                    $display (\"%m :                             Write Burst Mode = Programmed Burst Length\");\r\n                end else if (Addr[9] === 1'b1) begin\r\n                    $display (\"%m :                             Write Burst Mode = Single Location Access\");\r\n                end else begin\r\n                    $display (\"%m :                             Write Burst Mode = Reserved\");\r\n                end\r\n            end\r\n\r\n            // Precharge to Load Mode Register\r\n            if (Pc_b0 === 1'b0 && Pc_b1 === 1'b0 && Pc_b2 === 1'b0 && Pc_b3 === 1'b0) begin\r\n                $display (\"%m : at time %t ERROR: all banks must be Precharge before Load Mode Register\", $time);\r\n            end\r\n\r\n            // Precharge to Load Mode Register\r\n            if (($time - RP_chk0 < tRP) || ($time - RP_chk1 < tRP) ||\r\n                ($time - RP_chk2 < tRP) || ($time - RP_chk3 < tRP)) begin\r\n                $display (\"%m : at time %t ERROR: tRP violation during Load Mode Register\", $time);\r\n            end\r\n\r\n            // Auto Refresh to Load Mode Register\r\n            if ($time - RFC_chk < tRFC) begin\r\n                $display (\"%m : at time %t ERROR: tRFC violation during Load Mode Register\", $time);\r\n            end\r\n\r\n            // Load Mode Register to Load Mode Register\r\n            if (MRD_chk < tMRD) begin\r\n                $display (\"%m : at time %t ERROR: tMRD violation during Load Mode Register\", $time);\r\n            end\r\n\r\n            // Reset MRD Counter\r\n            MRD_chk = 0;\r\n        end\r\n        \r\n        // Active Block (Latch Bank Address and Row Address)\r\n        if (Active_enable === 1'b1) begin\r\n            // Activate an open bank can corrupt data\r\n            if ((Ba === 2'b00 && Act_b0 === 1'b1) || (Ba === 2'b01 && Act_b1 === 1'b1) ||\r\n                (Ba === 2'b10 && Act_b2 === 1'b1) || (Ba === 2'b11 && Act_b3 === 1'b1)) begin\r\n                $display (\"%m : at time %t ERROR: Bank already activated -- data can be corrupted\", $time);\r\n            end\r\n\r\n            // Activate Bank 0\r\n            if (Ba === 2'b00 && Pc_b0 === 1'b1) begin\r\n                // Debug Message\r\n                if (Debug) begin\r\n                    $display (\"%m : at time %t ACT  : Bank = 0 Row = %d\", $time, Addr);\r\n                end\r\n\r\n                // ACTIVE to ACTIVE command period\r\n                if ($time - RC_chk0 < tRC) begin\r\n                    $display (\"%m : at time %t ERROR: tRC violation during Activate bank 0\", $time);\r\n                end\r\n\r\n                // Precharge to Activate Bank 0\r\n                if ($time - RP_chk0 < tRP) begin\r\n                    $display (\"%m : at time %t ERROR: tRP violation during Activate bank 0\", $time);\r\n                end\r\n\r\n                // Record variables\r\n                Act_b0 = 1'b1;\r\n                Pc_b0 = 1'b0;\r\n                B0_row_addr = Addr [addr_bits - 1 : 0];\r\n                RAS_chk0 = $time;\r\n                RC_chk0 = $time;\r\n                RCD_chk0 = $time;\r\n            end\r\n\r\n            if (Ba == 2'b01 && Pc_b1 == 1'b1) begin\r\n                // Debug Message\r\n                if (Debug) begin\r\n                    $display (\"%m : at time %t ACT  : Bank = 1 Row = %d\", $time, Addr);\r\n                end\r\n\r\n                // ACTIVE to ACTIVE command period\r\n                if ($time - RC_chk1 < tRC) begin\r\n                    $display (\"%m : at time %t ERROR: tRC violation during Activate bank 1\", $time);\r\n                end\r\n\r\n                // Precharge to Activate Bank 1\r\n                if ($time - RP_chk1 < tRP) begin\r\n                    $display (\"%m : at time %t ERROR: tRP violation during Activate bank 1\", $time);\r\n                end\r\n\r\n                // Record variables\r\n                Act_b1 = 1'b1;\r\n                Pc_b1 = 1'b0;\r\n                B1_row_addr = Addr [addr_bits - 1 : 0];\r\n                RAS_chk1 = $time;\r\n                RC_chk1 = $time;\r\n                RCD_chk1 = $time;\r\n            end\r\n\r\n            if (Ba == 2'b10 && Pc_b2 == 1'b1) begin\r\n                // Debug Message\r\n                if (Debug) begin\r\n                    $display (\"%m : at time %t ACT  : Bank = 2 Row = %d\", $time, Addr);\r\n                end\r\n\r\n                // ACTIVE to ACTIVE command period\r\n                if ($time - RC_chk2 < tRC) begin\r\n                    $display (\"%m : at time %t ERROR: tRC violation during Activate bank 2\", $time);\r\n                end\r\n\r\n                // Precharge to Activate Bank 2\r\n                if ($time - RP_chk2 < tRP) begin\r\n                    $display (\"%m : at time %t ERROR: tRP violation during Activate bank 2\", $time);\r\n                end\r\n\r\n                // Record variables\r\n                Act_b2 = 1'b1;\r\n                Pc_b2 = 1'b0;\r\n                B2_row_addr = Addr [addr_bits - 1 : 0];\r\n                RAS_chk2 = $time;\r\n                RC_chk2 = $time;\r\n                RCD_chk2 = $time;\r\n            end\r\n\r\n            if (Ba == 2'b11 && Pc_b3 == 1'b1) begin\r\n                // Debug Message\r\n                if (Debug) begin\r\n                    $display (\"%m : at time %t ACT  : Bank = 3 Row = %d\", $time, Addr);\r\n                end\r\n\r\n                // ACTIVE to ACTIVE command period\r\n                if ($time - RC_chk3 < tRC) begin\r\n                    $display (\"%m : at time %t ERROR: tRC violation during Activate bank 3\", $time);\r\n                end\r\n\r\n                // Precharge to Activate Bank 3\r\n                if ($time - RP_chk3 < tRP) begin\r\n                    $display (\"%m : at time %t ERROR: tRP violation during Activate bank 3\", $time);\r\n                end\r\n\r\n                // Record variables\r\n                Act_b3 = 1'b1;\r\n                Pc_b3 = 1'b0;\r\n                B3_row_addr = Addr [addr_bits - 1 : 0];\r\n                RAS_chk3 = $time;\r\n                RC_chk3 = $time;\r\n                RCD_chk3 = $time;\r\n            end\r\n\r\n            // Active Bank A to Active Bank B\r\n            if ((Prev_bank != Ba) && ($time - RRD_chk < tRRD)) begin\r\n                $display (\"%m : at time %t ERROR: tRRD violation during Activate bank = %d\", $time, Ba);\r\n            end\r\n\r\n            // Auto Refresh to Activate\r\n            if ($time - RFC_chk < tRFC) begin\r\n                $display (\"%m : at time %t ERROR: tRFC violation during Activate bank = %d\", $time, Ba);\r\n            end\r\n\r\n            // Load Mode Register to Active\r\n            if (MRD_chk < tMRD ) begin\r\n                $display (\"%m : at time %t ERROR: tMRD violation during Activate bank = %d\", $time, Ba);\r\n            end\r\n\r\n            // Record variables for checking violation\r\n            RRD_chk = $time;\r\n            Prev_bank = Ba;\r\n        end\r\n        \r\n        // Precharge Block\r\n        if (Prech_enable == 1'b1) begin\r\n            // Load Mode Register to Precharge\r\n            if ($time - MRD_chk < tMRD) begin\r\n                $display (\"%m : at time %t ERROR: tMRD violaiton during Precharge\", $time);\r\n            end\r\n\r\n            // Precharge Bank 0\r\n            if ((Addr[10] === 1'b1 || (Addr[10] === 1'b0 && Ba === 2'b00)) && Act_b0 === 1'b1) begin\r\n                Act_b0 = 1'b0;\r\n                Pc_b0 = 1'b1;\r\n                RP_chk0 = $time;\r\n\r\n                // Activate to Precharge\r\n                if ($time - RAS_chk0 < tRAS) begin\r\n                    $display (\"%m : at time %t ERROR: tRAS violation during Precharge\", $time);\r\n                end\r\n\r\n                // tWR violation check for write\r\n                if ($time - WR_chkm[0] < tWRm) begin\r\n                    $display (\"%m : at time %t ERROR: tWR violation during Precharge\", $time);\r\n                end\r\n            end\r\n\r\n            // Precharge Bank 1\r\n            if ((Addr[10] === 1'b1 || (Addr[10] === 1'b0 && Ba === 2'b01)) && Act_b1 === 1'b1) begin\r\n                Act_b1 = 1'b0;\r\n                Pc_b1 = 1'b1;\r\n                RP_chk1 = $time;\r\n\r\n                // Activate to Precharge\r\n                if ($time - RAS_chk1 < tRAS) begin\r\n                    $display (\"%m : at time %t ERROR: tRAS violation during Precharge\", $time);\r\n                end\r\n\r\n                // tWR violation check for write\r\n                if ($time - WR_chkm[1] < tWRm) begin\r\n                    $display (\"%m : at time %t ERROR: tWR violation during Precharge\", $time);\r\n                end\r\n            end\r\n\r\n            // Precharge Bank 2\r\n            if ((Addr[10] === 1'b1 || (Addr[10] === 1'b0 && Ba === 2'b10)) && Act_b2 === 1'b1) begin\r\n                Act_b2 = 1'b0;\r\n                Pc_b2 = 1'b1;\r\n                RP_chk2 = $time;\r\n\r\n                // Activate to Precharge\r\n                if ($time - RAS_chk2 < tRAS) begin\r\n                    $display (\"%m : at time %t ERROR: tRAS violation during Precharge\", $time);\r\n                end\r\n\r\n                // tWR violation check for write\r\n                if ($time - WR_chkm[2] < tWRm) begin\r\n                    $display (\"%m : at time %t ERROR: tWR violation during Precharge\", $time);\r\n                end\r\n            end\r\n\r\n            // Precharge Bank 3\r\n            if ((Addr[10] === 1'b1 || (Addr[10] === 1'b0 && Ba === 2'b11)) && Act_b3 === 1'b1) begin\r\n                Act_b3 = 1'b0;\r\n                Pc_b3 = 1'b1;\r\n                RP_chk3 = $time;\r\n\r\n                // Activate to Precharge\r\n                if ($time - RAS_chk3 < tRAS) begin\r\n                    $display (\"%m : at time %t ERROR: tRAS violation during Precharge\", $time);\r\n                end\r\n\r\n                // tWR violation check for write\r\n                if ($time - WR_chkm[3] < tWRm) begin\r\n                    $display (\"%m : at time %t ERROR: tWR violation during Precharge\", $time);\r\n                end\r\n            end\r\n\r\n            // Terminate a Write Immediately (if same bank or all banks)\r\n            if (Data_in_enable === 1'b1 && (Bank === Ba || Addr[10] === 1'b1)) begin\r\n                Data_in_enable = 1'b0;\r\n            end\r\n\r\n            // Precharge Command Pipeline for Read\r\n            if (Cas_latency_3 === 1'b1) begin\r\n                Command[2] = `PRECH;\r\n                Bank_precharge[2] = Ba;\r\n                A10_precharge[2] = Addr[10];\r\n            end else if (Cas_latency_2 === 1'b1) begin\r\n                Command[1] = `PRECH;\r\n                Bank_precharge[1] = Ba;\r\n                A10_precharge[1] = Addr[10];\r\n            end else if (Cas_latency_1 === 1'b1) begin\r\n                Command[0] = `PRECH;\r\n                Bank_precharge[0] = Ba;\r\n                A10_precharge[0] = Addr[10];\r\n            end\r\n        end\r\n        \r\n        // Burst terminate\r\n        if (Burst_term === 1'b1) begin\r\n            // Terminate a Write Immediately\r\n            if (Data_in_enable == 1'b1) begin\r\n                Data_in_enable = 1'b0;\r\n            end\r\n\r\n            // Terminate a Read Depend on CAS Latency\r\n            if (Cas_latency_3 === 1'b1) begin\r\n                Command[2] = `BST;\r\n            end else if (Cas_latency_2 == 1'b1) begin\r\n                Command[1] = `BST;\r\n            end else if (Cas_latency_1 == 1'b1) begin\r\n                Command[0] = `BST;\r\n            end\r\n\r\n            // Display debug message\r\n            if (Debug) begin\r\n                $display (\"%m : at time %t BST  : Burst Terminate\",$time);\r\n            end\r\n        end\r\n        \r\n        // Read, Write, Column Latch\r\n        if (Read_enable === 1'b1) begin\r\n            // Check to see if bank is open (ACT)\r\n            if ((Ba == 2'b00 && Pc_b0 == 1'b1) || (Ba == 2'b01 && Pc_b1 == 1'b1) ||\r\n                (Ba == 2'b10 && Pc_b2 == 1'b1) || (Ba == 2'b11 && Pc_b3 == 1'b1)) begin\r\n                $display(\"%m : at time %t ERROR: Bank is not Activated for Read\", $time);\r\n            end\r\n\r\n            // Activate to Read or Write\r\n            if ((Ba == 2'b00) && ($time - RCD_chk0 < tRCD) ||\r\n                (Ba == 2'b01) && ($time - RCD_chk1 < tRCD) ||\r\n                (Ba == 2'b10) && ($time - RCD_chk2 < tRCD) ||\r\n                (Ba == 2'b11) && ($time - RCD_chk3 < tRCD)) begin\r\n                $display(\"%m : at time %t ERROR: tRCD violation during Read\", $time);\r\n            end\r\n\r\n            // CAS Latency pipeline\r\n            if (Cas_latency_3 == 1'b1) begin\r\n                Command[2] = `READ;\r\n                Col_addr[2] = Addr;\r\n                Bank_addr[2] = Ba;\r\n            end else if (Cas_latency_2 == 1'b1) begin\r\n                Command[1] = `READ;\r\n                Col_addr[1] = Addr;\r\n                Bank_addr[1] = Ba;\r\n            end else if (Cas_latency_1 == 1'b1) begin\r\n                Command[0] = `READ;\r\n                Col_addr[0] = Addr;\r\n                Bank_addr[0] = Ba;\r\n            end\r\n\r\n            // Read interrupt Write (terminate Write immediately)\r\n            if (Data_in_enable == 1'b1) begin\r\n                Data_in_enable = 1'b0;\r\n\r\n                // Interrupting a Write with Autoprecharge\r\n                if (Auto_precharge[RW_interrupt_bank] == 1'b1 && Write_precharge[RW_interrupt_bank] == 1'b1) begin\r\n                    RW_interrupt_write[RW_interrupt_bank] = 1'b1;\r\n                    RW_interrupt_counter[RW_interrupt_bank] = 0;\r\n\r\n                    // Display debug message\r\n                    if (Debug) begin\r\n                        $display (\"%m : at time %t NOTE : Read interrupt Write with Autoprecharge\", $time);\r\n                    end\r\n                end\r\n            end\r\n\r\n            // Read with Auto Precharge\r\n            if (Addr[10] == 1'b1) begin\r\n                Auto_precharge[Ba] = 1'b1;\r\n                Count_precharge[Ba] = 0;\r\n                RW_interrupt_bank = Ba;\r\n                Read_precharge[Ba] = 1'b1;\r\n            end\r\n        end\r\n\r\n        // Write Command\r\n        if (Write_enable == 1'b1) begin\r\n            // Activate to Write\r\n            if ((Ba == 2'b00 && Pc_b0 == 1'b1) || (Ba == 2'b01 && Pc_b1 == 1'b1) ||\r\n                (Ba == 2'b10 && Pc_b2 == 1'b1) || (Ba == 2'b11 && Pc_b3 == 1'b1)) begin\r\n                $display(\"%m : at time %t ERROR: Bank is not Activated for Write\", $time);\r\n            end\r\n\r\n            // Activate to Read or Write\r\n            if ((Ba == 2'b00) && ($time - RCD_chk0 < tRCD) ||\r\n                (Ba == 2'b01) && ($time - RCD_chk1 < tRCD) ||\r\n                (Ba == 2'b10) && ($time - RCD_chk2 < tRCD) ||\r\n                (Ba == 2'b11) && ($time - RCD_chk3 < tRCD)) begin\r\n                $display(\"%m : at time %t ERROR: tRCD violation during Read\", $time);\r\n            end\r\n\r\n            // Latch Write command, Bank, and Column\r\n            Command[0] = `WRITE;\r\n            Col_addr[0] = Addr;\r\n            Bank_addr[0] = Ba;\r\n\r\n            // Write interrupt Write (terminate Write immediately)\r\n            if (Data_in_enable == 1'b1) begin\r\n                Data_in_enable = 1'b0;\r\n\r\n                // Interrupting a Write with Autoprecharge\r\n                if (Auto_precharge[RW_interrupt_bank] == 1'b1 && Write_precharge[RW_interrupt_bank] == 1'b1) begin\r\n                    RW_interrupt_write[RW_interrupt_bank] = 1'b1;\r\n\r\n                    // Display debug message\r\n                    if (Debug) begin\r\n                        $display (\"%m : at time %t NOTE : Read Bank %d interrupt Write Bank %d with Autoprecharge\", $time, Ba, RW_interrupt_bank);\r\n                    end\r\n                end\r\n            end\r\n\r\n            // Write interrupt Read (terminate Read immediately)\r\n            if (Data_out_enable == 1'b1) begin\r\n                Data_out_enable = 1'b0;\r\n                \r\n                // Interrupting a Read with Autoprecharge\r\n                if (Auto_precharge[RW_interrupt_bank] == 1'b1 && Read_precharge[RW_interrupt_bank] == 1'b1) begin\r\n                    RW_interrupt_read[RW_interrupt_bank] = 1'b1;\r\n\r\n                    // Display debug message\r\n                    if (Debug) begin\r\n                        $display (\"%m : at time %t NOTE : Write Bank %d interrupt Read Bank %d with Autoprecharge\", $time, Ba, RW_interrupt_bank);\r\n                    end\r\n                end\r\n            end\r\n\r\n            // Write with Auto Precharge\r\n            if (Addr[10] == 1'b1) begin\r\n                Auto_precharge[Ba] = 1'b1;\r\n                Count_precharge[Ba] = 0;\r\n                RW_interrupt_bank = Ba;\r\n                Write_precharge[Ba] = 1'b1;\r\n            end\r\n        end\r\n\r\n        /*\r\n            Write with Auto Precharge Calculation\r\n                The device start internal precharge when:\r\n                    1.  Meet minimum tRAS requirement\r\n                and 2.  tWR cycle(s) after last valid data\r\n                 or 3.  Interrupt by a Read or Write (with or without Auto Precharge)\r\n\r\n            Note: Model is starting the internal precharge 1 cycle after they meet all the\r\n                  requirement but tRP will be compensate for the time after the 1 cycle.\r\n        */\r\n        if ((Auto_precharge[0] == 1'b1) && (Write_precharge[0] == 1'b1)) begin\r\n            if ((($time - RAS_chk0 >= tRAS) &&                                                          // Case 1\r\n               (((Burst_length_1 == 1'b1 || Write_burst_mode == 1'b1) && Count_precharge [0] >= 1) ||   // Case 2\r\n                 (Burst_length_2 == 1'b1                              && Count_precharge [0] >= 2) ||\r\n                 (Burst_length_4 == 1'b1                              && Count_precharge [0] >= 4) ||\r\n                 (Burst_length_8 == 1'b1                              && Count_precharge [0] >= 8))) ||\r\n                 (RW_interrupt_write[0] == 1'b1 && RW_interrupt_counter[0] >= 1)) begin                 // Case 3\r\n                    Auto_precharge[0] = 1'b0;\r\n                    Write_precharge[0] = 1'b0;\r\n                    RW_interrupt_write[0] = 1'b0;\r\n                    Pc_b0 = 1'b1;\r\n                    Act_b0 = 1'b0;\r\n                    RP_chk0 = $time + tWRa;\r\n                    if (Debug) begin\r\n                        $display (\"%m : at time %t NOTE : Start Internal Auto Precharge for Bank 0\", $time);\r\n                    end\r\n            end\r\n        end\r\n        if ((Auto_precharge[1] == 1'b1) && (Write_precharge[1] == 1'b1)) begin\r\n            if ((($time - RAS_chk1 >= tRAS) &&                                                          // Case 1\r\n               (((Burst_length_1 == 1'b1 || Write_burst_mode == 1'b1) && Count_precharge [1] >= 1) ||   // Case 2\r\n                 (Burst_length_2 == 1'b1                              && Count_precharge [1] >= 2) ||\r\n                 (Burst_length_4 == 1'b1                              && Count_precharge [1] >= 4) ||\r\n                 (Burst_length_8 == 1'b1                              && Count_precharge [1] >= 8))) ||\r\n                 (RW_interrupt_write[1] == 1'b1 && RW_interrupt_counter[1] >= 1)) begin                 // Case 3\r\n                    Auto_precharge[1] = 1'b0;\r\n                    Write_precharge[1] = 1'b0;\r\n                    RW_interrupt_write[1] = 1'b0;\r\n                    Pc_b1 = 1'b1;\r\n                    Act_b1 = 1'b0;\r\n                    RP_chk1 = $time + tWRa;\r\n                    if (Debug) begin\r\n                        $display (\"%m : at time %t NOTE : Start Internal Auto Precharge for Bank 1\", $time);\r\n                    end\r\n            end\r\n        end\r\n        if ((Auto_precharge[2] == 1'b1) && (Write_precharge[2] == 1'b1)) begin\r\n            if ((($time - RAS_chk2 >= tRAS) &&                                                          // Case 1\r\n               (((Burst_length_1 == 1'b1 || Write_burst_mode == 1'b1) && Count_precharge [2] >= 1) ||   // Case 2\r\n                 (Burst_length_2 == 1'b1                              && Count_precharge [2] >= 2) ||\r\n                 (Burst_length_4 == 1'b1                              && Count_precharge [2] >= 4) ||\r\n                 (Burst_length_8 == 1'b1                              && Count_precharge [2] >= 8))) ||\r\n                 (RW_interrupt_write[2] == 1'b1 && RW_interrupt_counter[2] >= 1)) begin                 // Case 3\r\n                    Auto_precharge[2] = 1'b0;\r\n                    Write_precharge[2] = 1'b0;\r\n                    RW_interrupt_write[2] = 1'b0;\r\n                    Pc_b2 = 1'b1;\r\n                    Act_b2 = 1'b0;\r\n                    RP_chk2 = $time + tWRa;\r\n                    if (Debug) begin\r\n                        $display (\"%m : at time %t NOTE : Start Internal Auto Precharge for Bank 2\", $time);\r\n                    end\r\n            end\r\n        end\r\n        if ((Auto_precharge[3] == 1'b1) && (Write_precharge[3] == 1'b1)) begin\r\n            if ((($time - RAS_chk3 >= tRAS) &&                                                          // Case 1\r\n               (((Burst_length_1 == 1'b1 || Write_burst_mode == 1'b1) && Count_precharge [3] >= 1) ||   // Case 2\r\n                 (Burst_length_2 == 1'b1                              && Count_precharge [3] >= 2) ||\r\n                 (Burst_length_4 == 1'b1                              && Count_precharge [3] >= 4) ||\r\n                 (Burst_length_8 == 1'b1                              && Count_precharge [3] >= 8))) ||\r\n                 (RW_interrupt_write[3] == 1'b1 && RW_interrupt_counter[3] >= 1)) begin                 // Case 3\r\n                    Auto_precharge[3] = 1'b0;\r\n                    Write_precharge[3] = 1'b0;\r\n                    RW_interrupt_write[3] = 1'b0;\r\n                    Pc_b3 = 1'b1;\r\n                    Act_b3 = 1'b0;\r\n                    RP_chk3 = $time + tWRa;\r\n                    if (Debug) begin\r\n                        $display (\"%m : at time %t NOTE : Start Internal Auto Precharge for Bank 3\", $time);\r\n                    end\r\n            end\r\n        end\r\n\r\n        //  Read with Auto Precharge Calculation\r\n        //      The device start internal precharge:\r\n        //          1.  Meet minimum tRAS requirement\r\n        //      and 2.  CAS Latency - 1 cycles before last burst\r\n        //       or 3.  Interrupt by a Read or Write (with or without AutoPrecharge)\r\n        if ((Auto_precharge[0] == 1'b1) && (Read_precharge[0] == 1'b1)) begin\r\n            if ((($time - RAS_chk0 >= tRAS) &&                                                      // Case 1\r\n                ((Burst_length_1 == 1'b1 && Count_precharge[0] >= 1) ||                             // Case 2\r\n                 (Burst_length_2 == 1'b1 && Count_precharge[0] >= 2) ||\r\n                 (Burst_length_4 == 1'b1 && Count_precharge[0] >= 4) ||\r\n                 (Burst_length_8 == 1'b1 && Count_precharge[0] >= 8))) ||\r\n                 (RW_interrupt_read[0] == 1'b1)) begin                                              // Case 3\r\n                    Pc_b0 = 1'b1;\r\n                    Act_b0 = 1'b0;\r\n                    RP_chk0 = $time;\r\n                    Auto_precharge[0] = 1'b0;\r\n                    Read_precharge[0] = 1'b0;\r\n                    RW_interrupt_read[0] = 1'b0;\r\n                    if (Debug) begin\r\n                        $display (\"%m : at time %t NOTE : Start Internal Auto Precharge for Bank 0\", $time);\r\n                    end\r\n            end\r\n        end\r\n        if ((Auto_precharge[1] == 1'b1) && (Read_precharge[1] == 1'b1)) begin\r\n            if ((($time - RAS_chk1 >= tRAS) &&\r\n                ((Burst_length_1 == 1'b1 && Count_precharge[1] >= 1) || \r\n                 (Burst_length_2 == 1'b1 && Count_precharge[1] >= 2) ||\r\n                 (Burst_length_4 == 1'b1 && Count_precharge[1] >= 4) ||\r\n                 (Burst_length_8 == 1'b1 && Count_precharge[1] >= 8))) ||\r\n                 (RW_interrupt_read[1] == 1'b1)) begin\r\n                    Pc_b1 = 1'b1;\r\n                    Act_b1 = 1'b0;\r\n                    RP_chk1 = $time;\r\n                    Auto_precharge[1] = 1'b0;\r\n                    Read_precharge[1] = 1'b0;\r\n                    RW_interrupt_read[1] = 1'b0;\r\n                    if (Debug) begin\r\n                        $display (\"%m : at time %t NOTE : Start Internal Auto Precharge for Bank 1\", $time);\r\n                    end\r\n            end\r\n        end\r\n        if ((Auto_precharge[2] == 1'b1) && (Read_precharge[2] == 1'b1)) begin\r\n            if ((($time - RAS_chk2 >= tRAS) &&\r\n                ((Burst_length_1 == 1'b1 && Count_precharge[2] >= 1) || \r\n                 (Burst_length_2 == 1'b1 && Count_precharge[2] >= 2) ||\r\n                 (Burst_length_4 == 1'b1 && Count_precharge[2] >= 4) ||\r\n                 (Burst_length_8 == 1'b1 && Count_precharge[2] >= 8))) ||\r\n                 (RW_interrupt_read[2] == 1'b1)) begin\r\n                    Pc_b2 = 1'b1;\r\n                    Act_b2 = 1'b0;\r\n                    RP_chk2 = $time;\r\n                    Auto_precharge[2] = 1'b0;\r\n                    Read_precharge[2] = 1'b0;\r\n                    RW_interrupt_read[2] = 1'b0;\r\n                    if (Debug) begin\r\n                        $display (\"%m : at time %t NOTE : Start Internal Auto Precharge for Bank 2\", $time);\r\n                    end\r\n            end\r\n        end\r\n        if ((Auto_precharge[3] == 1'b1) && (Read_precharge[3] == 1'b1)) begin\r\n            if ((($time - RAS_chk3 >= tRAS) &&\r\n                ((Burst_length_1 == 1'b1 && Count_precharge[3] >= 1) || \r\n                 (Burst_length_2 == 1'b1 && Count_precharge[3] >= 2) ||\r\n                 (Burst_length_4 == 1'b1 && Count_precharge[3] >= 4) ||\r\n                 (Burst_length_8 == 1'b1 && Count_precharge[3] >= 8))) ||\r\n                 (RW_interrupt_read[3] == 1'b1)) begin\r\n                    Pc_b3 = 1'b1;\r\n                    Act_b3 = 1'b0;\r\n                    RP_chk3 = $time;\r\n                    Auto_precharge[3] = 1'b0;\r\n                    Read_precharge[3] = 1'b0;\r\n                    RW_interrupt_read[3] = 1'b0;\r\n                    if (Debug) begin\r\n                        $display(\"%m : at time %t NOTE : Start Internal Auto Precharge for Bank 3\", $time);\r\n                    end\r\n            end\r\n        end\r\n\r\n        // Internal Precharge or Bst\r\n        if (Command[0] == `PRECH) begin                         // Precharge terminate a read with same bank or all banks\r\n            if (Bank_precharge[0] == Bank || A10_precharge[0] == 1'b1) begin\r\n                if (Data_out_enable == 1'b1) begin\r\n                    Data_out_enable = 1'b0;\r\n                end\r\n            end\r\n        end else if (Command[0] == `BST) begin                  // BST terminate a read to current bank\r\n            if (Data_out_enable == 1'b1) begin\r\n                Data_out_enable = 1'b0;\r\n            end\r\n        end\r\n\r\n        if (Data_out_enable == 1'b0) begin\r\n            Dq_reg <= #tOH {data_bits{1'bz}};\r\n        end\r\n\r\n        // Detect Read or Write command\r\n        if (Command[0] == `READ) begin\r\n            Bank = Bank_addr[0];\r\n            Col = Col_addr[0];\r\n            Col_brst = Col_addr[0];\r\n            case (Bank_addr[0])\r\n                2'b00 : Row = B0_row_addr;\r\n                2'b01 : Row = B1_row_addr;\r\n                2'b10 : Row = B2_row_addr;\r\n                2'b11 : Row = B3_row_addr;\r\n            endcase\r\n            Burst_counter = 0;\r\n            Data_in_enable = 1'b0;\r\n            Data_out_enable = 1'b1;\r\n        end else if (Command[0] == `WRITE) begin\r\n            Bank = Bank_addr[0];\r\n            Col = Col_addr[0];\r\n            Col_brst = Col_addr[0];\r\n            case (Bank_addr[0])\r\n                2'b00 : Row = B0_row_addr;\r\n                2'b01 : Row = B1_row_addr;\r\n                2'b10 : Row = B2_row_addr;\r\n                2'b11 : Row = B3_row_addr;\r\n            endcase\r\n            Burst_counter = 0;\r\n            Data_in_enable = 1'b1;\r\n            Data_out_enable = 1'b0;\r\n        end\r\n\r\n        // DQ buffer (Driver/Receiver)\r\n        if (Data_in_enable == 1'b1) begin                                   // Writing Data to Memory\r\n            // Array buffer\r\n            case (Bank)\r\n                2'b00 : Dq_dqm = Bank0 [{Row, Col}];\r\n                2'b01 : Dq_dqm = Bank1 [{Row, Col}];\r\n                2'b10 : Dq_dqm = Bank2 [{Row, Col}];\r\n                2'b11 : Dq_dqm = Bank3 [{Row, Col}];\r\n            endcase\r\n\r\n            // Dqm operation\r\n            if (Dqm[0] == 1'b0) begin\r\n                Dq_dqm [ 7 :  0] = Dq [ 7 :  0];\r\n            end\r\n            if (Dqm[1] == 1'b0) begin\r\n                Dq_dqm [15 :  8] = Dq [15 :  8];\r\n            end\r\n            if (Dqm[2] == 1'b0) begin\r\n                Dq_dqm [23 : 16] = Dq [23 : 16];\r\n            end\r\n            if (Dqm[3] == 1'b0) begin\r\n                Dq_dqm [31 : 24] = Dq [31 : 24];\r\n            end\r\n\r\n            // Write to memory\r\n            case (Bank)\r\n                2'b00 : Bank0 [{Row, Col}] = Dq_dqm;\r\n                2'b01 : Bank1 [{Row, Col}] = Dq_dqm;\r\n                2'b10 : Bank2 [{Row, Col}] = Dq_dqm;\r\n                2'b11 : Bank3 [{Row, Col}] = Dq_dqm;\r\n            endcase\r\n\r\n            // Display debug message\r\n            if (Dqm !== 4'b1111) begin\r\n                // Record tWR for manual precharge\r\n                WR_chkm [Bank] = $time;\r\n\r\n                if (Debug) begin\r\n                    $display(\"%m : at time %t WRITE: Bank = %d Row = %d, Col = %d, Data = %h\", $time, Bank, Row, Col, Dq_dqm);\r\n                end\r\n            end else begin\r\n                if (Debug) begin\r\n                    $display(\"%m : at time %t WRITE: Bank = %d Row = %d, Col = %d, Data = Hi-Z due to DQM\", $time, Bank, Row, Col);\r\n                end\r\n            end\r\n\r\n            // Advance burst counter subroutine\r\n            #tHZ Burst_decode;\r\n\r\n        end else if (Data_out_enable == 1'b1) begin                         // Reading Data from Memory\r\n            // Array buffer\r\n            case (Bank)\r\n                2'b00 : Dq_dqm = Bank0[{Row, Col}];\r\n                2'b01 : Dq_dqm = Bank1[{Row, Col}];\r\n                2'b10 : Dq_dqm = Bank2[{Row, Col}];\r\n                2'b11 : Dq_dqm = Bank3[{Row, Col}];\r\n            endcase\r\n\r\n            // Dqm operation\r\n            if (Dqm_reg0 [0] == 1'b1) begin\r\n                Dq_dqm [ 7 :  0] = 8'bz;\r\n            end\r\n            if (Dqm_reg0 [1] == 1'b1) begin\r\n                Dq_dqm [15 :  8] = 8'bz;\r\n            end\r\n            if (Dqm_reg0 [2] == 1'b1) begin\r\n                Dq_dqm [23 : 16] = 8'bz;\r\n            end\r\n            if (Dqm_reg0 [3] == 1'b1) begin\r\n                Dq_dqm [31 : 24] = 8'bz;\r\n            end\r\n\r\n            // Display debug message\r\n            if (Dqm_reg0 !== 4'b1111) begin\r\n                Dq_reg = #tAC Dq_dqm;\r\n                if (Debug) begin\r\n                    $display(\"%m : at time %t READ : Bank = %d Row = %d, Col = %d, Data = %h\", $time, Bank, Row, Col, Dq_reg);\r\n                end\r\n            end else begin\r\n                Dq_reg = #tHZ {data_bits{1'bz}};\r\n                if (Debug) begin\r\n                    $display(\"%m : at time %t READ : Bank = %d Row = %d, Col = %d, Data = Hi-Z due to DQM\", $time, Bank, Row, Col);\r\n                end\r\n            end\r\n\r\n            // Advance burst counter subroutine\r\n            Burst_decode;\r\n        end\r\n    end\r\n\r\n    // Burst counter decode\r\n    task Burst_decode;\r\n        begin\r\n            // Advance Burst Counter\r\n            Burst_counter = Burst_counter + 1;\r\n\r\n            // Burst Type\r\n            if (Mode_reg[3] == 1'b0) begin                                  // Sequential Burst\r\n                Col_temp = Col + 1;\r\n            end else if (Mode_reg[3] == 1'b1) begin                         // Interleaved Burst\r\n                Col_temp[2] =  Burst_counter[2] ^  Col_brst[2];\r\n                Col_temp[1] =  Burst_counter[1] ^  Col_brst[1];\r\n                Col_temp[0] =  Burst_counter[0] ^  Col_brst[0];\r\n            end\r\n\r\n            // Burst Length\r\n            if (Burst_length_2) begin                                       // Burst Length = 2\r\n                Col [0] = Col_temp [0];\r\n            end else if (Burst_length_4) begin                              // Burst Length = 4\r\n                Col [1 : 0] = Col_temp [1 : 0];\r\n            end else if (Burst_length_8) begin                              // Burst Length = 8\r\n                Col [2 : 0] = Col_temp [2 : 0];\r\n            end else begin                                                  // Burst Length = FULL\r\n                Col = Col_temp;\r\n            end\r\n\r\n            // Burst Read Single Write            \r\n            if (Write_burst_mode == 1'b1) begin\r\n                Data_in_enable = 1'b0;\r\n            end\r\n\r\n            // Data Counter\r\n            if (Burst_length_1 == 1'b1) begin\r\n                if (Burst_counter >= 1) begin\r\n                    Data_in_enable = 1'b0;\r\n                    Data_out_enable = 1'b0;\r\n                end\r\n            end else if (Burst_length_2 == 1'b1) begin\r\n                if (Burst_counter >= 2) begin\r\n                    Data_in_enable = 1'b0;\r\n                    Data_out_enable = 1'b0;\r\n                end\r\n            end else if (Burst_length_4 == 1'b1) begin\r\n                if (Burst_counter >= 4) begin\r\n                    Data_in_enable = 1'b0;\r\n                    Data_out_enable = 1'b0;\r\n                end\r\n            end else if (Burst_length_8 == 1'b1) begin\r\n                if (Burst_counter >= 8) begin\r\n                    Data_in_enable = 1'b0;\r\n                    Data_out_enable = 1'b0;\r\n                end\r\n            end\r\n        end\r\n    endtask\r\n\r\n    // Timing Parameters for -6 CL3\r\n    specify\r\n        specparam\r\n            tAH  =  1.0,                                        // Addr, Ba Hold Time\r\n            tAS  =  1.5,                                        // Addr, Ba Setup Time\r\n            tCH  =  2.5,                                        // Clock High-Level Width\r\n            tCL  =  2.5,                                        // Clock Low-Level Width\r\n            tCK  =  6.0,                                        // Clock Cycle Time\r\n            tDH  =  1.0,                                        // Data-in Hold Time\r\n            tDS  =  1.5,                                        // Data-in Setup Time\r\n            tCKH =  1.0,                                        // CKE Hold  Time\r\n            tCKS =  1.5,                                        // CKE Setup Time\r\n            tCMH =  1.0,                                        // CS#, RAS#, CAS#, WE#, DQM# Hold  Time\r\n            tCMS =  1.5;                                        // CS#, RAS#, CAS#, WE#, DQM# Setup Time\r\n        $width    (posedge Clk,           tCH);\r\n        $width    (negedge Clk,           tCL);\r\n        $period   (negedge Clk,           tCK);\r\n        $period   (posedge Clk,           tCK);\r\n        $setuphold(posedge Clk,    Cke,   tCKS, tCKH);\r\n        $setuphold(posedge Clk,    Cs_n,  tCMS, tCMH);\r\n        $setuphold(posedge Clk,    Cas_n, tCMS, tCMH);\r\n        $setuphold(posedge Clk,    Ras_n, tCMS, tCMH);\r\n        $setuphold(posedge Clk,    We_n,  tCMS, tCMH);\r\n        $setuphold(posedge Clk,    Addr,  tAS,  tAH);\r\n        $setuphold(posedge Clk,    Ba,    tAS,  tAH);\r\n        $setuphold(posedge Clk,    Dqm,   tCMS, tCMH);\r\n        $setuphold(posedge Dq_chk, Dq,    tDS,  tDH);\r\n    endspecify\r\n\r\nendmodule\r\n");
